// Zet het resultaat klaar voor de workflow 'Resultaat ophalen'.
// Google Sheets houdt maximaal 50.000 tekens per cel, en een forum met
// volledige rapporten van Digger gaat daar zo overheen. Daarom knippen we
// het forum in stukken van 45.000 en zetten die in aparte kolommen.

const bron = $input.first().json;
const trigger = $('When chat message received').first().json;

const forumTekst = JSON.stringify(bron.forum ?? []);
const STUK = 45000;
const stukken = [];
for (let i = 0; i < forumTekst.length; i += STUK) {
  stukken.push(forumTekst.slice(i, i + STUK));
}

// Past het echt niet, dan liever het advies zonder overleg dan een
// afgekapte JSON die straks niet te lezen is.
if (stukken.length > 4) {
  stukken.length = 0;
  stukken.push('[]');
}

return [{
  json: {
    beurtId: trigger.beurtId ?? '',
    sessionId: trigger.sessionId ?? '',
    output: String(bron.output ?? '').slice(0, 49000),
    forum1: stukken[0] ?? '',
    forum2: stukken[1] ?? '',
    forum3: stukken[2] ?? '',
    forum4: stukken[3] ?? '',
    tijd: new Date().toISOString(),
  },
}];
